<!doctype html><html lang="id"><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:12px;color:#202520}h1{font-size:22px;margin-bottom:4px}.muted{color:#68716a}.meta{line-height:1.7}table{width:100%;border-collapse:collapse;margin-top:24px}td,th{border:1px solid #cdd3ce;padding:9px}th{background:#f0f3f0;text-align:left}.right{text-align:right}.total{font-size:15px}</style></head><body><h1>Invoice Internet</h1><p class="muted"><b>{{config('app.name')}}</b></p><p class="meta">Invoice: <b>{{$invoice->invoice_number}}</b><br>Periode: {{$invoice->period}}<br>Jatuh Tempo: {{$invoice->due_date->format('d-m-Y')}}<br>Status: {{strtoupper($invoice->status)}}</p><p class="meta">Nama: <b>{{$invoice->customer->name}}</b><br>ID Pelanggan: {{$invoice->customer->customer_code}}<br>Jenis layanan: {{strtoupper($invoice->customer->service_type)}}<br>Paket: {{$invoice->customer->package?->name ?? '—'}}</p><table><thead><tr><th>Deskripsi</th><th class="right">Jumlah</th></tr></thead><tbody>@forelse($invoice->items as $item)<tr><td>{{$item->description}}</td><td class="right">Rp {{number_format($item->line_total,0,',','.')}}</td></tr>@empty<tr><td>{{$invoice->customer->package?->name ?? 'Layanan Internet'}}</td><td class="right">Rp {{number_format($invoice->subtotal,0,',','.')}}</td></tr>@endforelse<tr><td>Subtotal</td><td class="right">Rp {{number_format($invoice->subtotal,0,',','.')}}</td></tr>@if($invoice->discount)<tr><td>Diskon</td><td class="right">− Rp {{number_format($invoice->discount,0,',','.')}}</td></tr>@endif @if($invoice->penalty)<tr><td>Denda</td><td class="right">Rp {{number_format($invoice->penalty,0,',','.')}}</td></tr>@endif @if($invoice->tax_amount)<tr><td>PPN ({{$invoice->tax_rate}}%)</td><td class="right">Rp {{number_format($invoice->tax_amount,0,',','.')}}</td></tr>@endif</tbody><tfoot><tr><th class="total">Total</th><th class="right total">Rp {{number_format($invoice->total,0,',','.')}}</th></tr></tfoot></table></body></html>
